"""Seal original ambient controls and native arithmetic without admitting an execution adapter."""
import json,zipfile
from setup_deseq2_reference import ROOT,pin,save
from signac_scan_evidence import pack,unpack,byte_pin
from audit_soupx_ambient_controls import audit


def main():
    base=ROOT/'build/literature-review/soupx-runtime';target=ROOT/'docs/literature/soupx-ambient-core-development';assert not target.exists();build=json.loads((base/'ambient-core-build-1/COMPLETED.json').read_bytes());validation=json.loads((base/'ambient-core-validation-5/COMPLETED.json').read_bytes());example=json.loads((base/'ambient-core-example-1/COMPLETED.json').read_bytes());diagnosis=json.loads((base/'poisson-diagnosis-1/COMPLETED.json').read_bytes());assert all(p['artifact']==build['artifact'] for p in [validation,example]) and diagnosis['original_fit_objects_preserved'];checks={}
    for version,attempt in [('1.6.2',2),('1.3.0',3)]:
        prefix=base/f'ambient-controls-{version}-{attempt}';checks[version]=audit(json.loads((prefix/'inputs.json').read_bytes()),json.loads((prefix/'controls.json').read_bytes()),diagnosis['versions'][version])
    files={};attempts=['ambient-controls-1.6.2-1','ambient-controls-1.6.2-2','ambient-controls-1.3.0-1','ambient-controls-1.3.0-2','ambient-controls-1.3.0-3','ambient-core-build-1','poisson-diagnosis-1','ambient-core-example-1']+[f'ambient-core-validation-{i}' for i in range(1,6)]
    for name in attempts:
        for path in (base/name).rglob('*'):
            parts=path.relative_to(base/name).parts
            if not path.is_file() or path.suffix in ['.jar','.pyc'] or '__pycache__' in parts or any(p.startswith('Rtmp') for p in parts):continue
            files[path.relative_to(ROOT).as_posix()]=path.read_bytes()
    parent_folder=ROOT/'docs/literature/tfidf-markers-development';parent_proof=json.loads((parent_folder/'VALIDATION.json').read_bytes());parent_files=unpack(parent_folder/'controls.zip',parent_proof);assert pin(parent_folder/'controls.zip')==parent_proof['archive']
    for name in ['licenses/upstream-SoupX-GPL-2.txt','licenses/NOTICE.txt']:files[name]=parent_files[name]
    files['retained-attempts-diagnosis.json']=(json.dumps(dict(first_current_reference='Owned sparse exporter called the wrong summary generic without attaching Matrix; no completed control set was claimed. Corrected only the reference program.',first_legacy_reference='The10-function historical API has no alloc helper; used version-specific guards without changing any upstream function.',second_legacy_reference='Historical source archive has no inst/extdata/toyData. Reused the exact official1.6.2 toy fixture for both APIs with independent source/fixture pins; did not substitute source versions.',first_native_compile='Replaced an ambiguous Double::isNaN test reference with an explicit lambda.',second_native_validation='The owned test expected JSON objects for non-expression rows; actual captured rows are ordered Boolean arrays. Fixed only the test decoder.',third_native_validation='Initial tests incorrectly asserted source iterative GLM equals the analytical MLE within arithmetic tolerance. Read preserved original response/offset vectors without refitting and documented the nonzero original GLM score. Final tests compare the native analytical value against the independent analytical limit, while retaining the different original estimate.',fourth_native_compile='Renamed a duplicate local test variable. No source/reference bytes or methods changed.',final_scope='Arithmetic/core and closed request contracts only; Java execution, runtime admission and corrected user-result auditing remain unfinished.'),indent=2)+'\n').encode('utf8')
    jar=ROOT/build['artifact']['path'];parent=ROOT/build['parent_artifact']['path'];assert pin(jar)=={k:build['artifact'][k] for k in ['bytes','sha256']}
    with zipfile.ZipFile(parent) as before,zipfile.ZipFile(jar) as after:
        old={n:byte_pin(before.read(n)) for n in before.namelist()};new={n:byte_pin(after.read(n)) for n in after.namelist()};assert all(new[n]==v for n,v in old.items()) and set(new)-set(old)==set(build['added_entries'])
        for name in build['added_entries']:files['candidate-owned-entry/'+name]=after.read(name)
    for label,entries in [('parent',old),('candidate',new)]:files['artifact-'+label+'-entries.json']=(json.dumps(entries,sort_keys=True,indent=2)+'\n').encode('utf8')
    names={p.relative_to(ROOT).as_posix() for p in (ROOT/'tools/literature').glob('*soupx_ambient*') if p.is_file()};names.update(['tools/literature/diagnose_soupx_poisson.py','tools/literature/diagnose_soupx_poisson.R','src/main/java/org/jlinalg/singlecell/SoupXAmbient.java','src/main/java/org/jlinalg/cli/SoupXWorkflowRequest.java','src/test/java/org/jlinalg/cli/SoupXAmbientTest.java','src/test/java/org/jlinalg/cli/SoupXWorkflowRequestTest.java','docs/literature/SOUPX_AMBIENT_DEVELOPMENT.md']);names.update(p.relative_to(ROOT).as_posix() for folder in ['examples/soupx-ambient-core','src/test/resources/org/jlinalg/singlecell/soupx-ambient'] for p in (ROOT/folder).glob('*') if p.is_file());pins={n:pin(ROOT/n) for n in sorted(names)};files.update({'current-source/'+n:(ROOT/n).read_bytes() for n in pins})
    for proof in [build,validation,example,diagnosis]:assert all(pin(ROOT/n)==v for n,v in proof['source_pins'].items())
    target.mkdir();(target/'.gitattributes').write_text('* -text\n',encoding='utf8',newline='\n');layout=pack(target/'controls.zip',files);assert (target/'controls.zip').stat().st_size<100000000;warning=target/'WARNINGS.md';warning.write_text('''# SoupX ambient core: warnings and required actions

**EXECUTION ADAPTER UNFINISHED.** Native arithmetic and internal request contracts do not admit a user ambient-RNA analysis or corrected matrix. Do not treat original control execution as a completed Java adapter. SoupX remains missing; the catalog remains76 new scoped integrations and255 missing. Read [the guide](../SOUPX_AMBIENT_DEVELOPMENT.md).

**ANALYTICAL AND ORIGINAL GLM ESTIMATES DIFFER.** Original global Poisson GLM fits report convergence at epsilon1e-8 but have nonzero scores. In both editions their rho differs from the analytical limit by7.198298485056043e-10 for estimated masks and2.589336106639806e-10 for the supplied mask. Native arithmetic matches the independently computed analytical limit. Original estimates/iterations/response/offset vectors and fit objects remain unchanged. Do not silently replace an upstream fit with the native ratio; confidence intervals, GLM iteration and STAN are separate.

**VERSIONED RETURN TYPES ARE DIFFERENT.** Historical1.3.0 autoEstCont returns a density-estimate data frame; current1.6.2 returns a channel with gamma-based estimation. Explicit application is required before using the legacy estimate for correction. forceAccept is current-only. Literal first cluster FALSE can bypass original cluster-level correction. Empty selected-droplet ranges return NaN profiles; retain and refuse their downstream use rather than recoding them. No identifier repair, omitted counts, implicit coordinate sums or transformed-count substitution is permitted.

**USER ACTION:** use only the documented native arithmetic API/example at this checkpoint. Supply complete literal axes, unique exact nonnegative integer coordinates, explicit profile ranges, marker gene sets and masks/clusters. Caller biological assumptions are not inferred. Retain invalid/failed inputs and original diagnostics. An actual permitted upstream runtime/profile is needed for original analysis; if unavailable, preserve SKIP3 with the exact missing dependency/action and skip dependent analysis. No silent version fallback or original-function patching.

**REFERENCE LIMITS:** identical official toy data tested both unchanged source APIs under modern R4.6.1/Matrix1.7-5. These are not biological cohorts, paper commits or historical R environments. The55 control cases include failures and pathological original returns; they do not imply all cases admit analysis. Canonical executable, parent JAR entries, earlier scientific evidence and preexisting libraries remain unchanged. Full runtime supervision, source/output admission and atomic corrected-result validation remain outstanding. Cell Ranger remains excluded; the full250-paper goal stays active.
''',encoding='utf8',newline='\n')
    save(target/'VALIDATION.json',dict(schema_version=1,status='passed-native-SoupX-ambient-arithmetic-and-request-contracts',archive=pin(target/'controls.zip'),warnings_document=pin(warning),source_pins=pins,parent_proofs={'docs/literature/tfidf-markers-development/VALIDATION.json':pin(parent_folder/'VALIDATION.json'),'docs/literature/tfidf-markers-development/controls.zip':pin(parent_folder/'controls.zip')},artifact=build['artifact'],parent_artifact=build['parent_artifact'],unchanged_parent_entries=build['unchanged_parent_entries'],added_entries=build['added_entries'],canonical_executable_unchanged=build['canonical_executable_unchanged'],tests_per_JVM=28,JVMs=3,original_cases=55,reference_audits=checks,executed_native_example=True,native_core_admitted=True,ambient_workflow_admitted=False,implementation_credit=False,whole_paper_reproduced=False,whole_goal_complete=False,**layout));(target/'SHA256SUMS').write_text(''.join(pin(target/n)['sha256']+'  '+n+'\n' for n in ['controls.zip','WARNINGS.md','VALIDATION.json']),encoding='utf8',newline='\n');print('Sealed',len(files),'logical files;',pin(target/'controls.zip')['bytes'],'archive bytes')


if __name__=='__main__':
    if not __debug__:raise RuntimeError('Never disable original/source/core checks')
    main()
